export function chatT(lang: AppLanguage, key: ChatMessageKey, vars?: Record<string, string | number>): string {
  const raw = CHAT_MESSAGES[lang]?.[key] ?? CHAT_MESSAGES.en[key] ?? key;
  if (!vars) return raw;
  return Object.entries(vars).reduce(
    (s, [k, v]) => s.split('{' + k + '}').join(String(v)),
    raw,
  );
}
